fun add(a, b):
	return a + b
end

fun factorial(n):
	if (n <= 1) then:
		return 1
	else:
		return n * factorial(n - 1)
	end
end

fun fibonacci(n):
	if (n <= 1) then:
		return n
	else:
		return fibonacci(n - 1) + fibonacci(n - 2)
	end
end

