// Optimized version using direct assignment and push
data = []
for (i in range(1, 50)):
	row = {}
	for (j in range(1, 10)):
		key = "col" + str(j)
		row[key] = i * j
	end
	push(data, row)
end

// Process the data with optimized approach
processed = []
for (row in data):
	new_row = {}
	for (j in range(1, 5)):
		key = "col" + str(j)
		if (key in row) then:
			new_key = "new_" + key
			new_row[new_key] = row[key] * 2
		end
	end
	push(processed, new_row)
end

