fun main():
	result = 5
	print("Result: " + str(result))

	// Test list operations
	nums = [1, 2, 3]
	print("Length: " + str(len(nums)))

	// Test conditionals
	if (result > 3) then:
		print("Result is greater than 3")
	else:
		print("Result is not greater than 3")
	end

	// Test while loop
	i = 0
	while (i < 2):
		print("Loop iteration: " + str(i))
		i = i + 1
	end
end

fun main():
	// Test break
	i = 0
	while (true):
		if (i >= 2) then:
			break
		end
		print("Break test: " + str(i))
		i = i + 1
	end

	// Test continue
	j = 0
	while (j < 3):
		j = j + 1
		if (j == 2) then:
			continue
		end
		print("Continue test: " + str(j))
	end
end

fun helper(x):
	return x * 2
end

fun main():
	// Variables and assignments
	a = 10
	b = "hello"
	c = [1, 2, 3]
	d = {"key": "value"}

	// Function calls
	result = helper(5)
	print("Helper result: " + str(result))

	// Conditional with else
	if (a > 5) then:
		print("a is greater than 5")
	else:
		print("a is not greater than 5")
	end

	// Loop with for
	for (item in c):
		print("Item: " + str(item))
	end

	// Complex expressions
	expr = (a + 5) * 2 - 1
	print("Expression: " + str(expr))

	// Boolean logic
	flag = true and false
	print("Flag: " + str(flag))

	// String operations
	greeting = b + " world"
	print("Greeting: " + greeting)

	// Return value
	return 42
end

